    private val byLang: Map<String, SummaryStrings> = mapOf(
        "en" to en,
        "es" to es,
        "fr" to fr,
        "de" to de,
        "it" to it,
        "pt" to pt,
        "ru" to ru,
        "zh" to zh,
        "ja" to ja,
        "ms" to ms,
    )

    fun forLocale(locale: String?): SummaryStrings {
        if (locale.isNullOrBlank()) return en
        val lang = locale.substringBefore('-').substringBefore('_').lowercase()
        return byLang[lang] ?: en
    }
